import heapq


def toposort(nodes, edges):
    node_set = set(nodes)

    adjacency = {node: set() for node in node_set}
    indegree = {node: 0 for node in node_set}

    for source, target in edges:
        if source not in node_set or target not in node_set:
            raise ValueError(f"Edge references unknown node: ({source}, {target})")

        if target not in adjacency[source]:
            adjacency[source].add(target)
            indegree[target] += 1

    available = [node for node in node_set if indegree[node] == 0]
    heapq.heapify(available)

    order = []
    while available:
        node = heapq.heappop(available)
        order.append(node)

        for neighbor in adjacency[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(available, neighbor)

    if len(order) != len(node_set):
        raise ValueError("Graph contains a cycle")

    return order
